import React, { useState } from 'react';
import { Web3ReactProvider } from '@web3-react/core';
import { ethers } from 'ethers';
import {
  Container,
  Typography,
  Box,
  CssBaseline,
  AppBar,
  Toolbar,
  Button,
  Tabs,
  Tab,
} from '@mui/material';
import ProductList from './components/ProductList';
import AddProduct from './components/AddProduct';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import { injected } from './connectors';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import AdminLogin from './components/AdminLogin';

const theme = createTheme({
  palette: {
    mode: 'light',
    primary: {
      main: '#1976d2',
    },
    secondary: {
      main: '#dc004e',
    },
  },
});

function getLibrary(provider) {
  return new ethers.providers.Web3Provider(provider);
}

function App() {
  const [tabValue, setTabValue] = useState(0);
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Web3ReactProvider getLibrary={getLibrary}>
        <AppBar position="static">
          <Toolbar>
            <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
              Hệ Thống Đánh Giá Sản Phẩm Blockchain
            </Typography>
            {!isLoggedIn ? (
              <Button color="inherit" onClick={() => setTabValue(3)}>
                Đăng Nhập
              </Button>
            ) : (
              <Button color="inherit" onClick={() => setIsLoggedIn(false)}>
                Đăng Xuất
              </Button>
            )}
          </Toolbar>
        </AppBar>

        <Container maxWidth="lg">
          <Box sx={{ my: 4 }}>
            {isLoggedIn ? (
              <>
                <Tabs value={tabValue} onChange={handleTabChange}>
                  <Tab label="Danh Sách Sản Phẩm" />
                  <Tab label="Thêm Sản Phẩm" />
                  <Tab label="Quản Trị" />
                </Tabs>

                <Box sx={{ mt: 3 }}>
                  {tabValue === 0 && <ProductList />}
                  {tabValue === 1 && <AddProduct />}
                  {tabValue === 2 && <AdminPanel />}
                </Box>
              </>
            ) : (
              <Login onLoginSuccess={() => setIsLoggedIn(true)} />
            )}
          </Box>
        </Container>
      </Web3ReactProvider>
    </ThemeProvider>
  );
}

export default App;
